from hep_lfx import HepComponent, component, payload
from lfx.io import DataInput, Output
from lfx.schema import Data
class HepMode(HepComponent):
 display_name='选择检查目标来源'
 inputs=[DataInput(name="value",display_name="输入",required=True)]
 outputs=[Output(name='explicit',display_name='指定检查对',method='route_explicit',group_outputs=True),Output(name='rulesError',display_name='规则读取失败',method='route_rulesError',group_outputs=True),Output(name='noRules',display_name='没有启用规则',method='route_noRules',group_outputs=True),Output(name='rules',display_name='按启用规则',method='route_rules',group_outputs=True)]
 async def route_explicit(self)->Data:
  value=payload(self.value)
  selected=(await component("mode",value,self._id))["mode"]
  for name in ['explicit', 'rulesError', 'noRules', 'rules']:
   if name!=selected:self.stop(name)
  self.graph.exclude_branches_conditionally(self._id,[name for name in ['explicit', 'rulesError', 'noRules', 'rules'] if name!=selected])
  return Data(data=value)
